import json,glob
def would_fire(tid, window=6, distinct_max=2):
    msgs=json.load(open(tid+'.messages.json'))
    pairs=[]; pending=None
    for m in msgs:
        if m.get('role')=='assistant' and m.get('tool_calls'):
            pending=m['tool_calls'][0]['function']['arguments']
        elif m.get('role')=='tool' and pending is not None:
            pairs.append((pending,m['content'])); pending=None
    fires=0
    for i in range(window-1,len(pairs)):
        if len(set(pairs[i-window+1:i+1]))<=distinct_max: fires+=1
    return fires,len(pairs)
passcnt=0;passfire=0
for f in sorted(glob.glob('*.result.json')):
    d=json.load(open(f)); 
    if d.get('reward')==1:
        passcnt+=1
        fires,n=would_fire(d['task_id'])
        if fires>0:
            passfire+=1
            print('PASS-FIRE',d['task_id'],'fires',fires,'pairs',n)
print('total passing',passcnt,'passing that would fire',passfire)
